mkdir -p skills/OfficeBench/testbed/data && node -e "
const XLSX = require('xlsx');

// Create workbook and worksheet
const wb = XLSX.utils.book_new();
const data = [
  ['Flight Number', 'Origin', 'Destination', 'Date', 'Time'],
  ['FL6BD665', 'LAX', 'SFO', '2026-09-05', '09:00']
];
const ws = XLSX.utils.aoa_to_sheet(data);

// Set column widths
ws['!cols'] = [
  { wch: 15 }, // Flight Number
  { wch: 10 }, // Origin
  { wch: 12 }, // Destination
  { wch: 12 }, // Date
  { wch: 8 }   // Time
];

XLSX.utils.book_append_sheet(wb, ws, 'Flights');
XLSX.writeFile(wb, 'skills/OfficeBench/testbed/data/travel_expenses.xlsx');
console.log('File created successfully');
"

